'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>structuredClone(v);
const uid=()=>crypto.randomUUID().replaceAll('-','');
const icons={editor:'M4 5h16v14H4z M8 9h8 M8 13h5',templates:'M4 4h6v7H4z M14 4h6v7h-6z M4 15h6v5H4z M14 15h6v5h-6z',documents:'M6 3h9l4 4v14H6z M14 3v5h5 M9 12h7 M9 16h5',data:'M4 6c0-4 16-4 16 0s-16 4-16 0v12c0 4 16 4 16 0V6 M4 12c0 4 16 4 16 0',assets:'M3 4h18v16H3z M4 17l5-6 4 4 3-3 5 6 M15 8h2',queue:'M6 8V3h12v5 M6 17H3V8h18v9h-3 M6 13h12v8H6z M17 10h1',reports:'M4 3v18h17 M8 17v-5 M13 17V8 M18 17V4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M10 3h4l1 3 3 1 3 3v4l-3 1-1 3-3 3h-4l-1-3-3-1-3-3v-4l3-1 1-3z',help:'M9 9a3 3 0 1 1 4 3v3 M12 18h.1 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20'};
const svg=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.editor}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const S={boot:null,view:'editor',doc:null,page:0,element:0,resources:[],records:[{Rack:'A01',Port:'01',Type:'Fiber'},{Rack:'A01',Port:'02',Type:'Copper'},{Rack:'A02',Port:'01',Type:'Fiber'}],row:0,datasetName:'',datasetId:null,sourceId:null,sheets:[],sheet:'',settings:null,device:null,jobs:[],reports:[],logs:null,users:[],diag:null,preview:null,previewError:'',resourceId:null,resourceKind:null,dirty:false,libraryFilter:'',assetTab:'image',settingsTab:'general',range:{start:'',end:''}};
const page=()=>S.doc.pages[S.page];
const element=()=>page().elements[S.element];
function newElement(type='text'){return{id:uid(),type,x:2,y:4,w:type==='image'?12:type==='qr'?10:type==='barcode'?40:0,h:type==='image'?12:type==='qr'?10:6,text:type==='text'?'DC-{Rack}-{Port}':type==='qr'||type==='barcode'?'{Rack}-{Port}':'',font:'Segoe UI',size:12,bold:false,underline:false,align:'center',direction:'auto',rotation:0,asset:'',thickness:.2};}
function newLabel(){return{name:t('new'),kind:'general',model:S.boot?.model||'PT-E550W',width:S.boot?.default_width||24,length:65,auto_length:true,margin_before:2,margin_after:2,quality:S.boot?.default_quality||'standard',mirror:false,repeat:1,separator:' | ',separator_line:true,cable_gap:8,wrap_repeats:2,cells:6,pitch:12,border:false,elements:[newElement()]};}
function newDoc(){return{name:t('new'),pages:[newLabel()],rules:[],variables:{Rack:'A01',Port:'01'}};}
function toast(msg,error=false){const node=$('#toast');node.textContent=msg;node.className='visible'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.className='',error?8000:3500);}
async function api(url,method='GET',body){let response;try{response=await fetch('/api'+url,{method,headers:{'X-Studio-Request':'1','X-CSRF-Token':S.boot?.csrf||'',...(body instanceof FormData?{}:body!==undefined?{'Content-Type':'application/json'}:{})},body:body instanceof FormData?body:body!==undefined?JSON.stringify(body):undefined});}catch(e){throw Error('NETWORK_ERROR');}if(!response.ok){let value;try{value=await response.json();}catch{}let detail=value?.error||value?.detail||response.statusText;if(Array.isArray(detail))detail=detail.map(v=>v.loc.join('.')+': '+v.msg).join('\n');if(response.status===401&&url!='/login'){S.boot.user=null;render();}throw Error(typeof detail==='string'?detail:JSON.stringify(detail));}if(response.headers.get('content-type')?.includes('application/json'))return response.json();return response.blob();}
async function safely(work){try{return await work();}catch(e){toast(errorText(e.message),true);console.error(e);}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function jsonDownload(data,name){download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),name);}
function modal(html){$('#dialog-content').innerHTML=html;$('#dialog').showModal();}
function closeModal(){$('#dialog').close();}
function button(action,label,cls='',extra=''){return`<button type="button" class="${cls}" data-action="${action}" ${extra}>${h(t(label))}</button>`;}
function opt(values,selected){return values.map(item=>{const[v,key]=Array.isArray(item)?item:[item,item];return`<option value="${h(v)}" ${String(v)===String(selected)?'selected':''}>${h(t(key))}</option>`;}).join('');}
function field(key,label,value,type='text',attrs='',group='label'){return`<label>${h(t(label))}<input type="${type}" value="${h(value)}" data-${group}="${key}" ${attrs}></label>`;}
function check(key,label,value,group='label'){return`<label class="check"><input type="checkbox" data-${group}="${key}" ${value?'checked':''}>${h(t(label))}</label>`;}
function select(key,label,values,value,group='label'){return`<label>${h(t(label))}<select data-${group}="${key}">${opt(values,value)}</select></label>`;}
function labelSelect(key,label,values){return select(key,label,values,page()[key]);}
function badge(state,label){return`<span class="badge ${['reachable','completed','installed'].includes(state)?'good':['failed','offline','error'].includes(state)?'bad':['waiting','unknown','missing'].includes(state)?'warn':''}"><i class="dot ${state==='reachable'?'online':state==='offline'?'offline':''}"></i>${h(label||t(state))}</span>`;}
const resourceList=kind=>S.resources.filter(r=>r.kind===kind);
function userName(id){return S.users.find(u=>u.id===id)?.username||(id===S.boot.user.id?S.boot.user.username:id.slice(0,8));}
function formatDate(time){return new Date(time*1000).toLocaleString(language==='en'?'en-GB':language==='ar'?'ar':'fa-IR',{dateStyle:'short',timeStyle:'short'});}
async function bootstrap(){S.boot=await api('/bootstrap');if(!localStorage.getItem('studio-language'))language=S.boot.language;document.documentElement.lang=language;document.documentElement.dir=language==='en'?'ltr':'rtl';S.doc??=newDoc();if(S.boot.user){await refreshResources();await loadDevice();}render();}
async function refreshResources(){S.resources=await api('/resources');for(const font of resourceList('font')){const id='font-'+font.id;if(!document.getElementById(id)){const style=document.createElement('style');style.id=id;style.textContent=`@font-face{font-family:"uploaded-${font.id}";src:url("/api/assets/${font.id}")}`;document.head.appendChild(style);}}}
async function loadDevice(){S.device=await api('/printer/status');updateDevice();}
function updateDevice(){const footer=$('#device-status');if(footer&&S.device){footer.innerHTML=`<span class="dot ${S.device.state==='reachable'?'online':S.device.state==='offline'?'offline':''}"></span>${h(t(S.device.state==='reachable'?'online':S.device.state))}`;}const tag=$('#device-badge');if(tag&&S.device)tag.innerHTML=badge(S.device.state,t(S.device.detail));}
function render(){document.documentElement.lang=language;document.documentElement.dir=language==='en'?'ltr':'rtl';if(!S.boot?.user){renderLogin();return;}const isAdmin=S.boot.user.role==='admin';const nav=['editor','templates','documents','data','assets','queue','reports',...(isAdmin?['settings']:[]),'help'];$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="/static/icon.svg" alt=""><div><strong>Cable Label</strong><small>STUDIO / ${h(t('workspace'))}</small></div></div><nav class="nav">${nav.map(n=>`<button data-nav="${n}" class="${S.view===n?'active':''}">${svg(n)}${h(t(n))}</button>`).join('')}</nav><div class="sidebar-footer"><div class="model">BROTHER ${h(S.settings?.model||S.boot.model)}</div><div id="device-status"></div><div class="muted" style="margin-top:10px;color:#70928e">v${h(S.boot.version)} · LOCAL</div>${credits()}</div></aside><main class="main"><header class="topbar"><div class="breadcrumb">${h(t('workspace'))} / <strong>${h(t(S.view))}</strong></div><div class="top-actions"><select class="lang" id="language" aria-label="Language">${opt([['fa','فارسی'],['en','English'],['ar','العربية']],language)}</select><button class="small subtle" data-action="profile">${h(S.boot.user.username)}</button><span class="avatar">${h(S.boot.user.username[0].toUpperCase())}</span>${S.boot.auth_enabled?button('logout','logout','small subtle'):''}</div></header><div class="content" id="content"></div></main></div>`;renderView();updateDevice();}
function heading(title,desc,actions=''){return`<div class="page-heading"><div><h1>${h(t(title))}</h1><p>${h(t(desc))}</p></div><div class="actions">${actions}</div></div>`;}
function renderView(){const content=$('#content');if(!content)return;switch(S.view){case'editor':content.innerHTML=editorView();schedulePreview();break;case'templates':case'documents':content.innerHTML=libraryView();break;case'data':content.innerHTML=dataView();break;case'assets':content.innerHTML=assetsView();break;case'queue':content.innerHTML=queueView();break;case'reports':content.innerHTML=reportsView();break;case'settings':content.innerHTML=settingsView();break;case'help':content.innerHTML=helpView();break;}content.insertAdjacentHTML('beforeend',`<footer class="statusline"><span>${h(t('offlineReady'))}</span><span>Cable Label Studio · ${h(S.boot.version)} · <a href="https://github.com/aa70027/P-touch" target="_blank" rel="noopener noreferrer">GitHub ↗</a> · Amir Rahimi · ${h(t('freeLicense'))}</span></footer>`);}
async function navigate(view){S.view=view;if(view==='settings'){[S.settings,S.users,S.diag,S.logs]=await Promise.all([api('/settings'),api('/users'),api('/diagnostics'),api('/logs')]);}if(view==='queue')S.jobs=await api('/jobs');if(view==='reports')await loadReports();render();}
function editorView(){const p=page(),e=element();return heading('editor','editorDesc',button('new','new','subtle')+button('save-file','saveFile')+button('save-template','saveTemplate')+button('print-dialog','print','primary'))+`<div class="editor"><div><section class="card"><div class="card-title"><div class="actions"><input class="search" data-document="name" value="${h(S.doc.name)}" aria-label="${h(t('name'))}"><span class="badge">${h(t(S.dirty?'unsaved':'preview'))}</span></div><span class="muted">${h(t(p.kind))}</span></div><div class="layout-tabs">${['general','cable-flag','cable-wrap','patch-panel','faceplate','die-cut-flag','terminal-block','heat-shrink'].map(k=>`<button data-kind="${k}" class="${p.kind===k?'active':''}">${h(t(k))}</button>`).join('')}</div><div class="preview-toolbar"><div id="device-badge"></div><div class="actions">${button('preview','refresh','small subtle')}${button('export-png','export','small')}</div></div><div class="canvas" id="canvas"><div class="muted">${h(t('preview'))}…</div></div><div class="preview-footer"><span id="preview-meta">${h(t('printedArea'))}</span><span>${h(`${modelProfile(p.model).dpi} × ${p.quality==='high'?modelProfile(p.model).high_dpi:modelProfile(p.model).dpi} dpi`)}</span></div><div class="pages">${S.doc.pages.map((_,i)=>`<button class="small ${i===S.page?'active':''}" data-page="${i}">${h(t('page'))} ${i+1}</button>`).join('')}${button('add-page','newPage','small')}${S.doc.pages.length>1?button('delete-page','delete','small danger'):''}</div></section><section class="card bottom-grid"><div class="card-title"><div><h3>${h(t('data'))}</h3><span class="muted">${h(S.datasetName||t('noData'))}</span></div><div class="actions">${button('bind-data','bindData','small')}${button('rules','rules','small')}</div></div><div class="preview-toolbar"><span class="hint">${h(t('record'))} ${S.row+1} / ${S.records.length}</span><div class="actions"><button class="small" data-action="prev-row">‹</button><button class="small" data-action="next-row">›</button></div></div>${dataTable(S.records.slice(0,30),true)}${S.records.length>30?`<div class="hint card-body">${S.records.length} ${h(t('records'))}</div>`:''}</section></div><div class="stack"><section class="card"><div class="card-title"><h3>${h(t('labelProperties'))}</h3></div><div class="props"><div class="fieldgrid"><div class="span">${labelSelect('model','model',S.boot.profiles.map(p=>[p.id,p.name]))}</div>${labelSelect('width','width',modelProfile(p.model).widths.map(v=>[v,v+' mm']))}${field('length',['cable-flag','die-cut-flag'].includes(p.kind)?'flagLength':'length',p.length,'number',`step=".1" min="4.4" max="1000" ${p.auto_length?'disabled':''}`)}<div class="span">${check('auto_length','autoLength',p.auto_length)}</div>${field('margin_before','before',p.margin_before,'number','step=".1" min="0" max="127"')}${field('margin_after','after',p.margin_after,'number','step=".1" min="0" max="127"')}<div class="span">${labelSelect('quality','quality',qualityOptions(p.model))}</div>${field('repeat','repeat',p.repeat,'number','min="1" max="10000"')}<div>${check('mirror','mirror',p.mirror)}</div><div class="span">${check('border','border',p.border)}</div>${['cable-flag','die-cut-flag'].includes(p.kind)?`${field('cable_gap','cableGap',p.cable_gap,'number','step=".1" min="0"')}${field('separator','separator',p.separator)}<div class="span">${check('separator_line','separatorLine',p.separator_line)}</div>`:''}${p.kind==='cable-wrap'?field('wrap_repeats','wrapRepeats',p.wrap_repeats,'number','min="1" max="10"'):''}${['patch-panel','terminal-block'].includes(p.kind)?field('cells','cells',p.cells,'number','min="1" max="96"')+field('pitch','pitch',p.pitch,'number','step=".1" min="2"')+`<div class="span">${check('separator_line','separatorLine',p.separator_line)}</div>`:''}</div></div></section><section class="card"><div class="card-title"><h3>${h(t('elements'))}</h3><span class="muted">${p.elements.length}</span></div><div class="elements">${p.elements.map((item,i)=>`<div class="element-row ${i===S.element?'selected':''}" data-element-index="${i}"><span>${h(t(item.type))} · ${h(item.text||item.id.slice(0,6))}</span><button class="small subtle" data-action="duplicate-element" data-index="${i}" title="${h(t('duplicate'))}">⧉</button><button class="small subtle danger" data-action="delete-element" data-index="${i}" aria-label="${h(t('delete'))}">×</button></div>`).join('')}</div><div class="add-tools">${['text','image','line','rectangle','qr','barcode'].map(type=>`<button data-add="${type}">+ ${h(t(type))}</button>`).join('')}</div></section><section class="card"><div class="card-title"><h3>${h(t('element'))}</h3></div><div class="props">${e?elementProperties(e):`<p class="hint">${h(t('noSelection'))}</p>`}</div></section></div></div>`;}
function elementProperties(e){return`<div class="fieldgrid">${['text','qr','barcode'].includes(e.type)?`<label class="span">${h(t('content'))}<textarea data-element="text" dir="auto">${h(e.text)}</textarea></label><p class="hint span">${h(t('bindingHint'))}</p>`:''}${e.type==='image'?`<div class="span">${select('asset','selectImage',[['','—'],...resourceList('image').map(a=>[a.id,a.name])],e.asset,'element')}</div>`:''}${e.type==='text'?`<div class="span">${select('font','font',[...S.boot.fonts.map(f=>[f,f]),...resourceList('font').map(f=>[f.id,f.payload.family||f.name])],e.font,'element')}</div>${field('size','size',e.size,'number','min="3" max="96" step=".5"','element')}${select('align','alignment',['left','center','right'],e.align,'element')}<div>${check('bold','bold',e.bold,'element')}</div><div>${check('underline','underline',e.underline,'element')}</div><div class="span">${select('direction','direction',['auto','rtl','ltr'],e.direction,'element')}</div>`:''}<div class="section-label span">${h(t('position'))}</div>${field('x','X',e.x,'number','step=".1" min="0"','element')}${field('y','Y',e.y,'number','step=".1" min="0"','element')}${field('w','W',e.w,'number','step=".1" min="0"','element')}${field('h','H',e.h,'number','step=".1" min=".1"','element')}${select('rotation','rotation',[0,90,180,270].map(v=>[v,v+'°']),e.rotation,'element')}${['line','rectangle'].includes(e.type)?field('thickness','thickness',e.thickness,'number','step=".1" min=".1"','element'):''}</div>`;}
let previewTimer,previewVersion=0;
function schedulePreview(){clearTimeout(previewTimer);previewTimer=setTimeout(()=>safely(refreshPreview),300);}
async function refreshPreview(){if(S.view!=='editor')return;const version=++previewVersion;try{const result=await api('/preview','POST',{document:S.doc,page:S.page,row:S.records[S.row]||{},...sourceBinding()});if(version!==previewVersion||S.view!=='editor')return;S.preview=result;if(result.source_row&&S.sourceId&&S.sourceActive!==false)S.records[S.row]=result.source_row;S.previewError='';paintPreview();}catch(e){if(version!==previewVersion)return;S.previewError=e.message;paintPreview();}}
function paintPreview(){const canvas=$('#canvas');if(!canvas)return;if(S.previewError){canvas.innerHTML=`<div class="canvas-error">${h(errorText(S.previewError))}</div>`;return;}const result=S.preview;if(!result)return;const displayWidth=Math.min(850,Math.max(230,result.length_mm*7));const displayHeight=displayWidth*result.width_mm/result.length_mm;canvas.innerHTML=`<div class="tape-wrap"><div class="tape" id="tape" style="width:${displayWidth}px;height:${displayHeight}px;min-height:0"><img draggable="false" src="${result.image}" alt="${h(t('preview'))}">${page().elements.map((e,i)=>`<button class="hit ${i===S.element?'selected':''}" data-hit="${i}" aria-label="${h(t(e.type))}" style="left:${(Math.max(2,page().margin_before)+e.x)/result.length_mm*100}%;top:${e.y/result.width_mm*100}%;width:${(e.w||Math.max(7,interpolatedLength(e.text)*e.size*.2))/result.length_mm*100}%;height:${e.h/result.width_mm*100}%"></button>`).join('')}</div><div class="dimension">${result.length_mm} × ${result.width_mm} mm</div></div>`;$('#preview-meta').textContent=`${t('printedArea')}: ${result.printable_mm} mm · ${t('hardwareFeed')}: ${result.estimated_output_mm} mm`;if(result.warnings.length)canvas.insertAdjacentHTML('beforeend',`<div class="hint" style="position:absolute;bottom:8px;left:12px;right:12px;text-align:center">${result.warnings.map(w=>h(t(w))).join(' · ')}</div>`);}
function interpolatedLength(text){const row=S.records[S.row]||S.doc.variables;return text.replace(/\{([^{}]+)\}/g,(_,key)=>row[key]??'').length;}
function dataTable(records,editable=false){if(!records.length)return`<div class="empty">${h(t('noItems'))}</div>`;const columns=[...new Set(records.flatMap(r=>Object.keys(r)))];return`<div class="table-wrap"><table><thead><tr><th>#</th>${columns.map(k=>`<th>${h(k)}</th>`).join('')}${editable?'<th></th>':''}</tr></thead><tbody>${records.map((r,i)=>`<tr class="${i===S.row?'selected':''}"><td><button class="small subtle" data-record="${i}">${i+1}</button></td>${columns.map(k=>`<td>${editable?`<input data-cell-row="${i}" data-cell-column="${h(k)}" value="${h(r[k])}" aria-label="${h(k)} ${i+1}">`:h(r[k])}</td>`).join('')}${editable?`<td><button data-action="delete-row" data-index="${i}" class="small danger">×</button></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function libraryView(){const kind=S.view==='templates'?'template':'document';const items=resourceList(kind).filter(r=>r.name.toLowerCase().includes(S.libraryFilter.toLowerCase()));return heading(S.view,'copyShared',button('import-design','import')+button('new','new','primary'))+`<div class="split" style="margin-bottom:20px"><input id="library-search" class="search" value="${h(S.libraryFilter)}" placeholder="${h(t('search'))}"><span class="muted">${items.length} ${h(t(S.view))}</span></div><div class="cards">${items.map(item=>`<article class="card library-card"><div class="library-preview"><div class="template-symbol">${h(item.payload.pages?.[0]?.kind?.includes('flag')?'A01 | A01':item.payload.pages?.[0]?.kind==='patch-panel'?'01 │ 02 │ 03':'DC · A01 · 01')}</div></div><div class="library-content"><h3>${h(item.name)}</h3><div class="muted">${h(t(item.payload.pages?.[0]?.kind||'general'))} · ${item.payload.pages?.length||1} ${h(t('page'))} · ${h(item.payload.pages?.[0]?.width)} mm</div><div class="actions">${button('open-resource','open','primary small',`data-id="${item.id}"`)}${button('export-resource','export','small',`data-id="${item.id}"`)}${button('resource-scope',item.scope,'small',`data-id="${item.id}"`)}${item.owner===S.boot.user.id?button('delete-resource','delete','small danger',`data-id="${item.id}"`):''}</div><div class="muted" style="margin-top:10px">${h(userName(item.owner))} · ${h(formatDate(item.updated))}</div></div></article>`).join('')||`<div class="card empty">${h(t('noItems'))}</div>`}</div>`;}
function dataView(){return heading('data','dataDesc',button('pick-excel','pickExcel','primary')+button('upload-data','upload')+button('manual-data','manualData'))+`<div class="settings-grid"><section class="card"><div class="card-title"><h3>${h(t('source'))}</h3></div><div class="card-body stack"><div class="fieldgrid">${select('source','source',[['','—'],...resourceList('source').map(s=>[s.id,s.name])],S.sourceId||'','data')}<div class="span"><strong>${h(t('selectedSheets'))}</strong><div class="sheet-choices">${S.sheets.map(name=>`<label class="check"><input type="checkbox" data-sheet-check value="${h(name)}" ${(S.selectedSheets||[S.sheet]).includes(name)?'checked':''}>${h(name)}</label>`).join('')}</div></div>${select('encoding','encoding',[['utf-8-sig','UTF-8'],['cp1256','Windows-1256'],['utf-16','UTF-16']],S.encoding||'utf-8-sig','data')}${select('delimiter','delimiter',[['','auto'],[',',','],[';',';'],['\t','Tab'],['|','|']],S.delimiter||'','data')}</div><p class="hint">${h(t('maxUpload'))}</p>${S.resources.find(r=>r.id===S.sourceId)?.payload.live?`<p class="notice info">${h(t('liveHint'))}</p><div class="code">${h(S.resources.find(r=>r.id===S.sourceId).payload.linked_path)}</div>${button('replace-linked','replacePath')}`:''}<div class="actions">${button('read-source','reloadSource')}${button('save-dataset','saveDataset')}${button('use-data','useDataset','primary')}</div><div class="notice">${h(t('accessMissing'))}</div></div></section><section class="card"><div class="card-title"><h3>${h(t('dataset'))}</h3><span class="badge">${S.records.length} ${h(t('records'))}</span></div><div class="card-body"><div class="stack">${resourceList('dataset').map(d=>`<div class="split"><div><strong>${h(d.name)}</strong><div class="muted">${d.payload.records?.length||0} ${h(t('records'))}</div></div><div class="actions">${button('load-dataset','load','small',`data-id="${d.id}"`)}${button('resource-scope',d.scope,'small',`data-id="${d.id}"`)}${d.owner===S.boot.user.id?button('delete-resource','delete','small danger',`data-id="${d.id}"`):''}</div></div>`).join('')||`<p class="hint">${h(t('noItems'))}</p>`}</div></div></section></div><section class="card" style="margin-top:20px"><div class="card-title"><h3>${h(S.datasetName||t('dataset'))}</h3><div class="actions">${button('add-row','addRow','small')}${button('export-data','exportCsv','small')}</div></div>${dataTable(S.records.slice(0,100),true)}${S.records.length>100?`<div class="card-body hint">100 / ${S.records.length}</div>`:''}</section>`;}
function assetsView(){const kind=S.assetTab;return heading('assets','assetsDesc',button('upload-image','uploadImage')+button('upload-font','uploadFont','primary'))+`<div class="layout-tabs" style="padding:0 0 18px">${['image','font'].map(k=>`<button class="${kind===k?'active':''}" data-asset-tab="${k}">${h(t(k==='image'?'images':'fonts'))}</button>`).join('')}</div><div class="cards">${resourceList(kind).map(a=>`<article class="card library-card"><div class="library-preview">${kind==='image'?`<img src="/api/assets/${a.id}" alt="${h(a.name)}" loading="lazy">`:`<span style="font-family:uploaded-${a.id};font-size:28px">Aa · سلام</span>`}</div><div class="library-content"><h3>${h(a.name)}</h3><p class="muted">${h(a.payload.family||'')} · ${Math.ceil(a.payload.size/1024)} KB</p><div class="actions">${button('download-asset','download','small',`data-id="${a.id}"`)}${button('resource-scope',a.scope,'small',`data-id="${a.id}"`)}${a.owner===S.boot.user.id?button('delete-resource','delete','small danger',`data-id="${a.id}"`):''}</div></div></article>`).join('')||`<div class="card empty">${h(t('noItems'))}</div>`}</div>`;}
function queueView(){const waiting=S.jobs.find(j=>j.state==='waiting');return heading('queue','queueDesc',button('refresh-jobs','refresh')+button('print-dialog','print','primary'))+(waiting?`<div class="notice info split" style="margin-bottom:20px"><div><strong>${h(t('waiting'))}</strong><p>${h(t('nextHint'))} <span class="key">Enter</span> <span class="key">Space</span></p></div>${button('next-job','next','primary',`data-id="${waiting.id}"`)}</div>`:'')+`<div class="notice" style="margin-bottom:20px">${h(t('printAccuracy'))}</div><section class="card">${S.jobs.length?`<div class="table-wrap" style="max-height:65vh"><table><thead><tr>${['created','owner','state','progress','sent','simulated','details'].map(k=>`<th>${h(t(k))}</th>`).join('')}</tr></thead><tbody>${S.jobs.map(j=>`<tr><td>${h(formatDate(j.created))}<div class="muted mono">${j.id.slice(0,8)}</div></td><td>${h(userName(j.owner))}</td><td>${badge(j.state,t(j.state))}${j.error?`<div class="hint" style="color:#b55b55;white-space:normal;max-width:260px">${h(errorText(j.error))}</div>`:''}</td><td><div class="progress"><span style="width:${Math.min(100,(j.sent+j.simulated)/j.total*100)}%"></span></div><div class="muted mono">${j.sent+j.simulated} / ${j.total}</div></td><td>${j.sent}</td><td>${j.simulated}</td><td><div class="actions">${j.state==='waiting'?button('next-job','next','small primary',`data-id="${j.id}"`):''}${['queued','running','waiting'].includes(j.state)?button('cancel-job','cancel','small danger',`data-id="${j.id}"`):j.owner===S.boot.user.id?button('reprint-job','reprint','small',`data-id="${j.id}"`):''}${button('job-details','details','small',`data-id="${j.id}"`)}</div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${h(t('noItems'))}</div>`}</section>`;}
async function loadReports(){const query=new URLSearchParams();if(S.range.start)query.set('start',new Date(S.range.start+'T00:00:00').getTime()/1000);if(S.range.end)query.set('end',new Date(S.range.end+'T23:59:59').getTime()/1000);S.reports=await api('/reports?'+query);}
function reportsView(){const sums=key=>S.reports.reduce((v,r)=>v+(r[key]||0),0);const max=Math.max(1,...S.reports.map(r=>r.sent));return heading('reports','reportsDesc',button('export-reports','exportCsv'))+`<div class="actions" style="margin-bottom:20px">${field('start','dateFrom',S.range.start,'date','','range')}${field('end','dateTo',S.range.end,'date','','range')}${button('refresh-reports','apply')}</div><div class="stats">${['jobs','sent','simulated','failed'].map(k=>`<div class="card stat"><span class="number">${sums(k)}</span><span class="caption">${h(t(k))}</span></div>`).join('')}</div><div class="notice" style="margin-bottom:20px">${h(t('printAccuracy'))}</div><section class="card"><div class="card-title"><h3>${h(t('sent'))}</h3></div><div class="bar-chart">${S.reports.map(r=>`<div class="bar-column"><span>${r.sent}</span><div class="bar" style="height:${Math.max(2,r.sent/max*80)}px"></div><span>${h(r.username)}</span></div>`).join('')}</div><div class="table-wrap"><table><thead><tr>${['username','jobs','requested','sent','confirmed','simulated','failed','cancelled','interrupted'].map(k=>`<th>${h(t(k==='requested'?'total':k))}</th>`).join('')}</tr></thead><tbody>${S.reports.map(r=>`<tr>${['username','jobs','requested','sent','confirmed','simulated','failed','cancelled','interrupted'].map(k=>`<td>${h(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;}
function settingsView(){if(!S.settings)return'';const v=S.settings;return heading('settings','settingsDesc',button('save-settings','save','primary'))+`<div class="layout-tabs" style="padding:0 0 22px">${['general','connections','updates','users','logs','diagnostics'].map(k=>`<button data-settings-tab="${k}" class="${S.settingsTab===k?'active':''}">${h(t(k==='general'?'settings':k))}</button>`).join('')}</div>`+(S.settingsTab==='connections'?connectionView():S.settingsTab==='updates'?updatesView():S.settingsTab==='general'?`<div class="settings-grid"><div class="stack"><section class="card"><div class="card-title"><h3>${h(t('printer'))}</h3><span>${badge(S.diag?.printer?.driver_installed?'installed':'missing',t(S.diag?.printer?.driver_installed?'installed':'missing'))}</span></div><div class="card-body fieldgrid">${select('connection','connection',[['usb','usb'],['wifi','wifi']],v.connection,'setting')}<div class="span">${select('printer','printer',[['','—'],...(S.diag?.printer.printers||[]).map(p=>[p.name,p.name])],v.printer,'setting')}</div>${field('ip','ip',v.ip,'text','dir="ltr" placeholder="192.168.1.100"','setting')}${field('printer_port','printerPort',v.printer_port,'number','min="1" max="65535"','setting')}${field('timeout','timeout',v.timeout,'number','min="10" max="600"','setting')}${select('default_width','defaultWidth',modelProfile(v.model).widths.map(n=>[n,n+' mm']),v.default_width,'setting')}<div class="span">${select('default_quality','defaultQuality',qualityOptions(v.model),v.default_quality,'setting')}</div><div class="span hint">${h(t(S.diag?.printer.detail||'SELECT_PRINTER'))}</div><a class="span" href="${h(S.diag?.driver_url||'#')}" target="_blank" rel="noreferrer">${h(t('getDriver'))} ↗</a></div></section><section class="card"><div class="card-title"><h3>${h(t('cutPolicy'))}</h3></div><div class="card-body fieldgrid">${[['cut_between_pages','betweenPages'],['cut_end_record','endRecord'],['cut_between_files','betweenFiles'],['cut_end_file','endFile']].map(([k,l])=>select(k,l,modelProfile(v.model).cuts||['full','half','none'],v[k],'setting')).join('')}<p class="hint span">${h(t('cutHint'))}</p></div></section></div><div class="stack"><section class="card"><div class="card-title"><h3>${h(t('application'))}</h3></div><div class="card-body fieldgrid">${field('port','appPort',v.port,'number','min="1024" max="65535"','setting')}${select('language','language',[['fa','فارسی'],['en','English'],['ar','العربية']],v.language,'setting')}${field('log_retention_days','retention',v.log_retention_days,'number','min="1" max="3650"','setting')}<div class="span">${check('auto_start','autoStart',v.auto_start,'setting')}${check('auth_enabled','authEnabled',v.auth_enabled,'setting')}</div><p class="hint span">${h(t('authHint'))}</p><div class="span notice">${h(t('restartNeeded'))}</div><div class="actions span">${button('restart','restart')}${button('shutdown','shutdown','danger')}</div></div></section><section class="card"><div class="card-title"><h3>${h(t('backup'))}</h3></div><div class="card-body stack"><p class="hint">${h(t('dataPath'))}</p><div class="code">${h(S.diag?.data_dir||'')}</div>${button('backup','backup')}<p class="hint">${h(t('helpBackup'))}</p></div></section></div></div>`:S.settingsTab==='users'?usersView():S.settingsTab==='logs'?logsView():diagnosticsView());}
function usersView(){return`<section class="card"><div class="card-title"><h3>${h(t('users'))}</h3>${button('new-user','create','primary')}</div><div class="table-wrap"><table><thead><tr>${['username','role','scope','action'].map(k=>`<th>${h(t(k))}</th>`).join('')}</tr></thead><tbody>${S.users.map(u=>`<tr><td>${h(u.username)} ${u.disabled?badge('offline',t('disabled')):''}</td><td>${h(t(u.role))}</td><td>${Object.entries(u.share).filter(([k,v])=>v).map(([k])=>h(t(({template:'templates',document:'documents',dataset:'dataset',image:'images',font:'fonts',source:'source'})[k]||k))).join(' · ')||h(t('private'))}</td><td>${button('edit-user','edit','small',`data-id="${u.id}"`)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function logsView(){return`<div class="stack"><section class="card"><div class="card-title"><h3>${h(t('audit'))}</h3><div class="actions">${button('refresh-logs','refresh','small')}${button('export-logs','export','small')}</div></div><div class="table-wrap"><table><thead><tr>${['created','username','action','detail'].map(k=>`<th>${h(t(k))}</th>`).join('')}</tr></thead><tbody>${(S.logs?.audit||[]).map(r=>`<tr><td>${h(formatDate(r.time))}</td><td>${h(r.username||r.user_id)}</td><td class="mono">${h(r.action)}</td><td class="mono">${h(r.detail)}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><div class="card-title"><h3>${h(t('application'))}</h3></div><pre class="logs">${h(S.logs?.application||'')}</pre></section></div>`;}
function diagnosticsView(){return`<section class="card"><div class="card-title"><h3>${h(t('diagnostics'))}</h3>${button('refresh-diagnostics','refresh','small')}</div><div class="card-body stack"><div class="notice info">${h(S.diag?.shaping||'')}</div><p>${h(t('driver'))}: ${h(t(S.diag?.printer.driver_installed?'installed':'missing'))}</p><p>${h(t(S.diag?.printer.detail||'unknown'))}</p><p>${h(t('accessDriver'))}: ${h(S.diag?.access_drivers.join(', ')||t('missing'))}</p>${!S.diag?.access_drivers.length?`<div class="notice">${h(t('accessMissing'))}</div>`:''}<div class="actions"><a href="${h(S.diag?.driver_url)}" target="_blank" rel="noreferrer">${h(t('getDriver'))} ↗</a><a href="${h(S.diag?.access_url)}" target="_blank" rel="noreferrer">${h(t('accessDriver'))} ↗</a></div><p class="hint">${h(t('hardwareHelp'))}</p></div></section>`;}
function helpView(){return heading('help','helpDesc')+`<section class="card help"><div class="card-body"><h2>${h(t('studio'))}</h2>${['helpStart','helpDesign','helpData','helpPrint','helpUsers','helpBackup'].map(k=>`<p>${h(t(k))}</p>`).join('')}<h3 style="margin-top:25px">${h(t('hardwareNotes'))}</h3><p>${h(t('hardwareHelp'))}</p><p>${h(t('printAccuracy'))}</p><h3 style="margin-top:25px">${h(t('formula'))}</h3><pre class="logs">IF(EMPTY(COL("X")), "", "A")\nCONCAT(COL("Rack"), "-", PAD(COL("Port"), 2))\nCOL("Type") == "Fiber"</pre><p>${h(t('formulaHint'))}</p><p class="hint">${h(t('fullGuide'))}</p></div></section>`;}
function renderLogin(){$('#app').innerHTML=`<section class="card login"><img src="/static/icon.svg" alt=""><h1>${h(t('studio'))}</h1><p class="muted">${h(t('loginDesc'))}</p><form id="login-form" class="stack"><label>${h(t('username'))}<input name="username" autocomplete="username" required></label><label>${h(t('password'))}<input name="password" type="password" autocomplete="current-password" required></label><button class="primary">${h(t('login'))}</button></form><select id="language" style="margin-top:22px">${opt([['fa','فارسی'],['en','English'],['ar','العربية']],language)}</select>${credits()}</section>`;}
async function saveDialog(kind){modal(`<h2>${h(t(kind==='template'?'saveTemplate':'saveFile'))}</h2><div class="stack">${field('resourceName','name',S.doc.name,'text','','dialog')}${select('scope','scope',['inherit','private','shared'],'inherit','dialog')}</div><div class="actions">${button('confirm-save','save','primary',`data-kind="${kind}"`)}</div>`);}
function userDialog(user,isProfile=false){const value=user||{username:'',role:'user',share:{},disabled:false};modal(`<h2>${h(t(isProfile?'profile':'users'))}</h2><div class="fieldgrid">${field('username','username',value.username,'text','autocomplete="username"','dialog')}${field('password',user?'newPassword':'password','','password','autocomplete="new-password"','dialog')}${!isProfile?select('role','role',['user','admin'],value.role,'dialog'):''}${!isProfile?check('disabled','disabled',value.disabled,'dialog'):''}<div class="span section-label">${h(t('shareDefaults'))}</div>${[['template','templates'],['document','documents'],['image','images'],['font','fonts'],['dataset','dataset'],['source','source']].map(([k,l])=>check('share-'+k,l,!!value.share[k],'dialog')).join('')}</div><div class="actions">${button('save-user','save','primary',`data-id="${user?.id||''}" data-profile="${isProfile}"`)}</div>`);}
function dialogValues(){return Object.fromEntries($$('[data-dialog]',$('#dialog-content')).map(n=>[n.dataset.dialog,n.type==='checkbox'?n.checked:n.type==='number'?Number(n.value):n.value]));}
function rulesDialog(){modal(`<h2>${h(t('rules'))}</h2><p class="hint">${h(t('formulaHint'))}</p><div id="rule-list">${S.doc.rules.map((r,i)=>ruleRow(r,i)).join('')}</div><div class="actions">${button('add-rule','addRule')}</div><label style="margin-top:18px">${h(t('variables'))}<textarea id="variables-json" class="code">${h(JSON.stringify(S.doc.variables,null,2))}</textarea></label><div class="actions">${button('save-rules','save','primary')}${button('test-rules','test')}</div><div id="rule-result" class="code" style="margin-top:12px"></div>`);}
function ruleRow(r,i){return`<div class="rule" data-rule="${i}"><label>${h(t('target'))}<input data-rule-field="target" value="${h(r.target||'B')}"></label><label>${h(t('condition'))}<input class="code" data-rule-field="when" value="${h(r.when||'True')}"></label><label>${h(t('formula'))}<input class="code" data-rule-field="value" value="${h(r.value||"'A'")}"></label><button data-action="remove-rule" class="danger small">×</button><label style="grid-column:2/4">${h(t('otherwise'))}<input class="code" data-rule-field="otherwise" value="${h(r.otherwise||'')}"></label></div>`;}
function collectRules(){return $$('.rule',$('#rule-list')).map(row=>Object.fromEntries($$('[data-rule-field]',row).map(n=>[n.dataset.ruleField,n.value])));}
function printDialog(existing=null){S.printExisting=existing;const count=S.records.length;modal(`<h2>${h(t('print'))}</h2><div class="fieldgrid">${field('copies','copies',existing?.copies||1,'number','min="1" max="10000"','dialog')}${field('file_copies','fileCopies',existing?.file_copies||1,'number','min="1" max="10000"','dialog')}${select('mode','mode',['continuous','confirm'],existing?.mode||'continuous','dialog')}${select('recordMode','records',[['all','allRecords'],['range','selectedRecords']],'all','dialog')}${field('fromRecord','fromRecord',1,'number',`min="1" max="${count}"`,'dialog')}${field('toRecord','toRecord',count,'number',`min="1" max="${count}"`,'dialog')}<div class="span">${check('simulation','simulation',existing?.simulation??false,'dialog')}</div></div><p class="hint" style="margin-top:12px">${h(t('simulationHint'))}</p><p class="notice" style="margin-top:10px">${h(t('physicalHint'))}</p>${!existing?`<h3 style="margin-top:20px">${h(t('selectFiles'))}</h3><p class="hint">${h(t('printFilesHint'))}</p><div style="max-height:130px;overflow:auto">${resourceList('document').map(d=>`<label class="check"><input type="checkbox" data-print-document="${d.id}">${h(d.name)}</label>`).join('')||`<span class="muted">${h(t('noItems'))}</span>`}</div>`:''}<div class="actions">${button('submit-print','submitPrint','primary')}</div>`);}
async function chooseFile(accept,work){const input=document.createElement('input');input.type='file';input.accept=accept;input.addEventListener('change',()=>safely(()=>work(input.files[0])));input.click();}
async function uploadFile(file,kind){const form=new FormData();form.append('file',file);const item=await api('/upload?kind='+kind,'POST',form);await refreshResources();return item;}
async function readSource(){if(!S.sourceId)throw Error('SELECT_SOURCE');const data=await api('/data/read','POST',{source:S.sourceId,sheet:S.sheet||null,sheets:S.selectedSheets??null,encoding:S.encoding||'utf-8-sig',delimiter:S.delimiter||null});S.records=data.records;S.sheets=data.sheets;S.selectedSheets=data.selected_sheets;S.sheet=data.sheet||'';S.sourceActive=true;S.row=0;S.datasetName=S.resources.find(r=>r.id===S.sourceId)?.name||'';S.datasetId=null;renderView();}

function csvExport(rows,name){if(!rows.length)return;const keys=[...new Set(rows.flatMap(r=>Object.keys(r)))];const safe=v=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return'"'+s.replaceAll('"','""')+'"';};const csv=[keys.map(safe).join(','),...rows.map(r=>keys.map(k=>safe(r[k])).join(','))].join('\r\n');download(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),name);}
async function act(action,node){switch(action){
 case'new':if(S.dirty&&!window.confirm(t('leaveDesign')))return;S.doc=newDoc();S.page=0;S.element=0;S.resourceId=null;S.resourceKind=null;S.dirty=false;await navigate('editor');break;
 case'save-file':await saveDialog('document');break;case'save-template':await saveDialog('template');break;
 case'confirm-save':{const v=dialogValues();const kind=node.dataset.kind;const own=S.resources.find(r=>r.id===S.resourceId)?.owner===S.boot.user.id;const ident=own&&S.resourceKind===kind?S.resourceId:null;S.doc.name=v.resourceName;const item=await api('/resources'+(ident?'/'+ident:''),ident?'PUT':'POST',{name:v.resourceName,kind,scope:v.scope,payload:S.doc});S.resourceId=item.id;S.resourceKind=kind;S.dirty=false;closeModal();await refreshResources();render();toast(t('saved'));break;}
 case'preview':await refreshPreview();break;
 case'export-png':download(await api('/export/png','POST',{document:S.doc,page:S.page,row:S.records[S.row]||{},...sourceBinding()}),'label.png');break;
 case'add-page':S.doc.pages.push(clone(page()));S.page=S.doc.pages.length-1;S.element=0;S.dirty=true;renderView();break;
 case'delete-page':if(S.doc.pages.length>1){S.doc.pages.splice(S.page,1);S.page=Math.max(0,S.page-1);S.element=0;S.dirty=true;renderView();}break;
 case'duplicate-element':{const e=clone(page().elements[+node.dataset.index]);e.id=uid();e.x+=1;page().elements.push(e);S.element=page().elements.length-1;S.dirty=true;renderView();break;}
 case'delete-element':page().elements.splice(+node.dataset.index,1);S.element=Math.min(S.element,page().elements.length-1);S.dirty=true;renderView();break;
 case'next-row':S.row=Math.min(S.records.length-1,S.row+1);renderView();break;case'prev-row':S.row=Math.max(0,S.row-1);renderView();break;
 case'bind-data':modal(`<h2>${h(t('bindData'))}</h2><div class="stack">${resourceList('dataset').map(d=>button('bind-dataset',d.name,'',`data-id="${d.id}"`)).join('')||`<p class="hint">${h(t('noItems'))}</p>`}${button('go-data','data','primary')}</div>`);break;
 case'go-data':closeModal();await navigate('data');break;
 case'load-dataset':case'bind-dataset':{const d=S.resources.find(r=>r.id===node.dataset.id);S.records=clone(d.payload.records);S.datasetId=d.id;S.datasetName=d.name;S.sourceId=d.payload.source||null;S.sheet=d.payload.sheet||'';S.selectedSheets=d.payload.sheets||null;S.sourceActive=d.payload.sourceActive!==false;S.row=0;closeModal();renderView();break;}
 case'rules':rulesDialog();break;
 case'add-rule':$('#rule-list').insertAdjacentHTML('beforeend',ruleRow({target:'B',when:'not EMPTY(COL("X"))',value:"'A'"},$$('.rule').length));break;
 case'remove-rule':node.closest('.rule').remove();break;
 case'save-rules':S.doc.rules=collectRules();try{S.doc.variables=JSON.parse($('#variables-json').value);}catch{throw Error('INVALID_JSON');}S.dirty=true;closeModal();renderView();break;
 case'test-rules':{const rules=collectRules();const row={...JSON.parse($('#variables-json').value),...S.records[S.row]};for(const r of rules){const condition=(await api('/formula','POST',{expression:r.when||'True',row})).value;if(condition)row[r.target]=(await api('/formula','POST',{expression:r.value,row})).value;else if(r.otherwise.trim())row[r.target]=(await api('/formula','POST',{expression:r.otherwise,row})).value;}$('#rule-result').textContent=JSON.stringify(row,null,2);break;}
 case'open-resource':{if(S.dirty&&!window.confirm(t('leaveDesign')))return;const r=S.resources.find(r=>r.id===node.dataset.id);S.doc=clone(r.payload);S.resourceId=r.id;S.resourceKind=r.kind;S.page=0;S.element=0;S.dirty=false;await navigate('editor');break;}
 case'export-resource':{const r=S.resources.find(r=>r.id===node.dataset.id);jsonDownload(r.payload,r.name+'.label.json');break;}
 case'import-design':await chooseFile('.json',async file=>{const doc=JSON.parse(await file.text());await api('/preview','POST',{document:doc,page:0,row:S.records[0]||{}});S.doc=doc;S.page=0;S.element=0;S.resourceId=null;S.dirty=true;await navigate('editor');});break;
 case'delete-resource':if(window.confirm(t('confirmDelete'))){await api('/resources/'+node.dataset.id,'DELETE');await refreshResources();renderView();toast(t('deleted'));}break;
 case'resource-scope':{const item=S.resources.find(r=>r.id===node.dataset.id);if(item.owner!==S.boot.user.id){toast(t(item.scope));return;}modal(`<h2>${h(t('scope'))}</h2>${select('scope','scope',['inherit','private','shared'],item.scope,'dialog')}<div class="actions">${button('save-scope','save','primary',`data-id="${item.id}"`)}</div>`);break;}
 case'save-scope':await api('/resources/'+node.dataset.id+'/scope','PATCH',{scope:dialogValues().scope});closeModal();await refreshResources();renderView();break;
 case'upload-data':await chooseFile('.xlsx,.xls,.xlsm,.csv,.tsv,.mdb,.accdb',async file=>{const item=await uploadFile(file,'source');S.sourceId=item.id;S.sheet='';S.selectedSheets=null;await readSource();});break;
 case'read-source':await readSource();break;
 case'manual-data':modal(`<h2>${h(t('manualData'))}</h2><textarea class="code" id="manual-records" style="height:300px">${h(JSON.stringify(S.records,null,2))}</textarea><div class="actions">${button('apply-manual-data','apply','primary')}</div>`);break;
 case'apply-manual-data':{let rows;try{rows=JSON.parse($('#manual-records').value);}catch{throw Error('INVALID_JSON');}if(!Array.isArray(rows)||!rows.length)throw Error('NO_RECORDS');if(rows.some(r=>!r||typeof r!=='object'||Array.isArray(r)))throw Error('ONLY_RECORD_OBJECTS');S.records=rows;S.row=0;S.datasetName='';S.sourceId=null;S.datasetId=null;closeModal();renderView();break;}
 case'save-dataset':modal(`<h2>${h(t('saveDataset'))}</h2>${field('name','name',S.datasetName||t('dataset'),'text','','dialog')}${select('scope','scope',['inherit','private','shared'],'inherit','dialog')}<div class="actions">${button('confirm-save-dataset','save','primary')}</div>`);break;
 case'confirm-save-dataset':{const v=dialogValues();const result=await api('/resources','POST',{name:v.name,kind:'dataset',scope:v.scope,payload:{records:S.records,source:S.sourceId,sheet:S.sheet,sheets:S.selectedSheets,sourceActive:S.sourceActive}});S.datasetId=result.id;S.datasetName=result.name;closeModal();await refreshResources();renderView();toast(t('saved'));break;}
 case'use-data':await navigate('editor');break;case'add-row':S.records.push(Object.fromEntries(Object.keys(S.records[0]||{Rack:'',Port:''}).map(k=>[k,''])));renderView();break;case'delete-row':if(S.records.length>1){S.records.splice(+node.dataset.index,1);S.row=Math.min(S.row,S.records.length-1);renderView();}break;
 case'export-data':csvExport(S.records,'dataset.csv');break;
 case'upload-image':await chooseFile('.png,.jpg,.jpeg,.bmp,.webp',async file=>{await uploadFile(file,'image');renderView();toast(t('saved'));});break;
 case'upload-font':await chooseFile('.ttf,.otf',async file=>{await uploadFile(file,'font');renderView();toast(t('saved'));});break;
 case'download-asset':{const item=S.resources.find(r=>r.id===node.dataset.id);download(await api('/assets/'+item.id),item.name);break;}
 case'print-dialog':printDialog();break;
 case'submit-print':{const v=dialogValues();let req;if(S.printExisting){req={...S.printExisting,source:null,copies:v.copies,file_copies:v.file_copies,mode:v.mode,simulation:v.simulation};}else{let records=S.records;if(v.recordMode==='range'){if(v.fromRecord<1||v.toRecord<v.fromRecord||v.toRecord>records.length)throw Error('INVALID_RECORD_RANGE');records=records.slice(v.fromRecord-1,v.toRecord);}if(!records.length)throw Error('NO_RECORDS');req={documents:[S.doc,...$$('[data-print-document]:checked').map(n=>S.resources.find(r=>r.id===n.dataset.printDocument).payload)],records,copies:v.copies,file_copies:v.file_copies,mode:v.mode,simulation:v.simulation};}if(!S.printExisting&&S.sourceId&&S.sourceActive!==false){Object.assign(req,sourceBinding(),{record_from:v.recordMode==='range'?v.fromRecord-1:0,record_to:v.recordMode==='range'?v.toRecord:null});}node.disabled=true;try{await api('/jobs','POST',req);closeModal();await navigate('queue');toast(t('jobQueued'));}finally{node.disabled=false;}break;}
 case'refresh-jobs':S.jobs=await api('/jobs');renderView();break;
 case'next-job':await api('/jobs/'+node.dataset.id+'/next','POST',{});S.jobs=await api('/jobs');renderView();break;
 case'cancel-job':await api('/jobs/'+node.dataset.id+'/cancel','POST',{});S.jobs=await api('/jobs');renderView();break;
 case'reprint-job':{const job=await api('/jobs/'+node.dataset.id);printDialog(job.payload.request);break;}
 case'job-details':{const job=await api('/jobs/'+node.dataset.id);modal(`<h2>${h(t('details'))}</h2><div class="stack"><p>${h(t('state'))}: ${h(t(job.state))}</p><p>${h(t('sent'))}: ${job.sent} · ${h(t('confirmed'))}: ${job.confirmed}</p><p class="hint">${h(t('printAccuracy'))}</p>${job.error?`<div class="notice error">${h(errorText(job.error))}</div>`:''}${job.simulated&&job.owner===S.boot.user.id?`<h3>${h(t('artifacts'))}</h3><div class="table-wrap"><table>${Array.from({length:Math.min(job.simulated,100)},(_,i)=>`<tr><td>${i+1}</td><td><a href="/api/jobs/${job.id}/artifacts/${i+1}/png" target="_blank">PNG</a></td><td>${modelProfile(job.payload.request?.documents?.[0]?.pages?.[0]?.model).transport==='raster'?`<a href="/api/jobs/${job.id}/artifacts/${i+1}/prn" download>PRN</a>`:'PNG / Windows driver'}</td></tr>`).join('')}</table></div>`:''}<pre class="logs">${h(JSON.stringify({settings:job.payload.settings,total:job.total},null,2))}</pre></div>`);break;}
 case'refresh-reports':await loadReports();renderView();break;case'export-reports':csvExport(S.reports,'usage.csv');break;
 case'save-settings':{const result=await api('/settings','PUT',S.settings);toast(t(result.restart_required?'restartNeeded':'saved'));if(result.reauthenticate){await bootstrap();}else{S.diag=await api('/diagnostics');await loadDevice();renderView();}break;}
 case'new-user':userDialog(null);break;case'edit-user':userDialog(S.users.find(u=>u.id===node.dataset.id));break;case'profile':userDialog(S.boot.user,true);break;
 case'save-user':{const v=dialogValues(),share=Object.fromEntries(Object.entries(v).filter(([k])=>k.startsWith('share-')).map(([k,v])=>[k.slice(6),v]));const body={username:v.username,password:v.password,role:v.role||S.boot.user.role,disabled:!!v.disabled,share};const profile=node.dataset.profile==='true';const url=profile?'/profile':'/users'+(node.dataset.id?'/'+node.dataset.id:'');await api(url,profile||node.dataset.id?'PUT':'POST',body);closeModal();if(S.boot.auth_enabled&&node.dataset.id===S.boot.user.id&&v.password){await bootstrap();}else{if(S.view==='settings')S.users=await api('/users');await bootstrap();}toast(t('saved'));break;}
 case'logout':await api('/logout','POST',{});await bootstrap();break;
 case'refresh-logs':S.logs=await api('/logs');renderView();break;case'export-logs':download(new Blob([S.logs.application],{type:'text/plain;charset=utf-8'}),'application.log');break;
 case'refresh-diagnostics':S.diag=await api('/diagnostics');await loadDevice();renderView();break;
 case'backup':download(await api('/backup','POST',{}),'CableLabelStudio-backup.zip');break;
 case'restart':{const result=await api('/restart','POST',{});toast(t('restartNeeded'));setTimeout(()=>location.href=result.url,5000);break;}
 case'shutdown':await api('/shutdown','POST',{});modal(`<h2>${h(t('stopped'))}</h2>`);break;
 }}
document.addEventListener('click',event=>safely(async()=>{const node=event.target.closest('[data-action],[data-nav],[data-kind],[data-page],[data-add],[data-element-index],[data-record],[data-asset-tab],[data-settings-tab]');if(!node)return;if(node.dataset.action){await act(node.dataset.action,node);return;}if(node.dataset.nav){await navigate(node.dataset.nav);return;}if(node.dataset.kind){page().kind=node.dataset.kind;S.dirty=true;if(['patch-panel','terminal-block'].includes(page().kind)){page().elements=[{...newElement(),text:'{#cell}',size:9,x:1}];S.element=0;}renderView();return;}if(node.dataset.page!==undefined){S.page=+node.dataset.page;S.element=0;renderView();return;}if(node.dataset.add){page().elements.push(newElement(node.dataset.add));S.element=page().elements.length-1;S.dirty=true;renderView();return;}if(node.dataset.elementIndex!==undefined){S.element=+node.dataset.elementIndex;renderView();return;}if(node.dataset.record!==undefined){S.row=+node.dataset.record;renderView();return;}if(node.dataset.assetTab){S.assetTab=node.dataset.assetTab;renderView();return;}if(node.dataset.settingsTab){S.settingsTab=node.dataset.settingsTab;renderView();}}));
document.addEventListener('change',event=>safely(async()=>{const n=event.target;const value=n.type==='checkbox'?n.checked:n.type==='number'?Number(n.value):n.value;if(n.id==='language'){language=value;localStorage.setItem('studio-language',language);render();return;}if(n.dataset.label){page()[n.dataset.label]=['width','wrap_repeats','cells'].includes(n.dataset.label)?Number(value):value;S.dirty=true;renderView();return;}if(n.dataset.element){element()[n.dataset.element]=n.dataset.element==='rotation'?Number(value):value;S.dirty=true;schedulePreview();return;}if(n.dataset.document){S.doc[n.dataset.document]=value;S.dirty=true;return;}if(n.dataset.setting){S.settings[n.dataset.setting]=['default_width'].includes(n.dataset.setting)?Number(value):value;return;}if(n.dataset.data){const key=n.dataset.data;if(key==='source'){S.sourceId=value;S.sheet='';S.sheets=[];S.selectedSheets=null;S.sourceActive=false;}else S[key]=value;return;}if(n.dataset.cellRow!==undefined){S.sourceActive=false;S.records[+n.dataset.cellRow][n.dataset.cellColumn]=value;schedulePreview();return;}if(n.dataset.range){S.range[n.dataset.range]=value;return;}if(n.id==='library-search'){S.libraryFilter=value;renderView();}}));
document.addEventListener('input',event=>{const n=event.target;if(n.dataset.element&&['text'].includes(n.dataset.element)){element()[n.dataset.element]=n.value;S.dirty=true;schedulePreview();}});
document.addEventListener('submit',event=>{if(event.target.id==='login-form'){event.preventDefault();safely(async()=>{const form=new FormData(event.target);await api('/login','POST',{username:form.get('username'),password:form.get('password')});await bootstrap();});}});
document.addEventListener('keydown',event=>{const editing=['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName);if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();safely(()=>saveDialog('document'));return;}if(editing||$('#dialog').open)return;if(S.view==='queue'&&['Enter',' '].includes(event.key)){const waiting=S.jobs.find(j=>j.state==='waiting');if(waiting){event.preventDefault();safely(()=>act('next-job',{dataset:{id:waiting.id}}));}return;}if(S.view==='editor'&&element()&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();const e=element(),step=event.shiftKey?1:.1;e.x=Math.max(0,e.x+(event.key==='ArrowLeft'?-step:event.key==='ArrowRight'?step:0));e.y=Math.max(0,e.y+(event.key==='ArrowUp'?-step:event.key==='ArrowDown'?step:0));S.dirty=true;renderView();}});
let drag=null;
document.addEventListener('pointerdown',event=>{const hit=event.target.closest('[data-hit]');if(!hit||!S.preview)return;const i=+hit.dataset.hit;S.element=i;const e=page().elements[i];drag={hit,id:event.pointerId,startX:event.clientX,startY:event.clientY,x:e.x,y:e.y,rect:$('#tape').getBoundingClientRect()};hit.setPointerCapture(event.pointerId);});
document.addEventListener('pointermove',event=>{if(!drag)return;const e=element();e.x=Math.round(Math.max(0,drag.x+(event.clientX-drag.startX)/drag.rect.width*S.preview.length_mm)*10)/10;e.y=Math.round(Math.max(0,drag.y+(event.clientY-drag.startY)/drag.rect.height*S.preview.width_mm)*10)/10;drag.hit.style.left=(Math.max(2,page().margin_before)+e.x)/S.preview.length_mm*100+'%';drag.hit.style.top=e.y/S.preview.width_mm*100+'%';});
document.addEventListener('pointerup',()=>{if(!drag)return;drag=null;S.dirty=true;renderView();});
window.addEventListener('beforeunload',event=>{if(S.dirty){event.preventDefault();event.returnValue='';}});
setInterval(()=>{if(!S.boot?.user||$('#dialog').open)return;safely(async()=>{if(S.view==='queue'){S.jobs=await api('/jobs');renderView();}});},2500);
setInterval(()=>{if(S.boot?.user)safely(loadDevice);},20000);
safely(bootstrap);
